<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { api,errorText,hasRole } from '../api'
import { time,shortId,useLoad } from '../composables'
import type { AgentRun,IncidentDetail } from '../types'
import PageState from '../components/PageState.vue'
import AgentReviewPanel from '../components/AgentReviewPanel.vue'
import AppIcon from '../components/AppIcon.vue'
import StatusBadge from '../components/StatusBadge.vue'
import LiveIndicator from '../components/LiveIndicator.vue'
import Badge from '../components/ui/Badge.vue'
import { agentStatus,nodeNames } from '../diagnosis'
import { hypothesisScore } from '../presentation'
const id=String(useRoute().params.id),{data,loading,error,load}=useLoad(async()=>{const run=await api<AgentRun>('/agent-runs/'+id);const incident=await api<IncidentDetail>('/incidents/'+run.incidentId);return {...run,incident:incident.incident,canOperate:incident.canOperate}}),busy=ref(false),reason=ref(''),saveError=ref('')
const active=computed(()=>data.value&&['QUEUED','RUNNING','WAITING_HUMAN'].includes(data.value.status))
async function retry(){busy.value=true;saveError.value='';try{await api('/agent-runs/'+id+'/retry',{method:'POST',body:{reason:reason.value}});reason.value='';await load()}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
function citationLink(sectionId:string){const section=data.value?.runbookEvidence.find(s=>s.sectionId===sectionId);return section?{path:'/runbooks/'+section.runbookId,query:{version:String(section.version),section:section.sectionId},hash:'#'+section.sectionId}:{path:'/targets/'+data.value?.targetId,query:{tab:'history'}}}
function refresh(){if(!document.hidden&&!loading.value)void load()}
onMounted(()=>{void load();window.addEventListener('focus',refresh)});const timer=setInterval(()=>{if(active.value)refresh()},3000);onUnmounted(()=>{clearInterval(timer);window.removeEventListener('focus',refresh)})
</script>
<template><RouterLink to="/diagnosis" class="back-link"><AppIcon name="arrow" :size="15" />AI 故障诊断</RouterLink><PageState :loading="loading&&!data" :error="error" @retry="load"><template v-if="data"><div class="page-heading"><div><div class="eyebrow ai">Diagnosis workspace</div><div class="title-line"><h1>{{ data.incident.targetName }}</h1><Badge :tone="data.status==='FAILED'?'danger':data.status==='WAITING_HUMAN'?'warning':'ai'">{{ agentStatus[data.status]||data.status }}</Badge><span class="env-tag">{{ data.modelName }}</span></div><p>诊断任务 <code>{{ shortId(data.id) }}</code> · {{ time(data.createdAt) }}</p></div><div class="actions"><LiveIndicator v-if="active" :seconds="3" :loading="loading" /><button class="btn" :disabled="loading" @click="load"><AppIcon name="refresh" :size="15" />刷新状态</button></div></div>
<div class="diagnosis-context"><AppIcon name="incident" :size="18" /><RouterLink :to="'/incidents/'+data.incidentId">{{ data.incident.summary }}</RouterLink><StatusBadge :value="data.incident.status" /><RouterLink :to="'/incidents/'+data.incidentId" class="text-link">事件时间线<AppIcon name="chevron" :size="14" /></RouterLink></div>
<div class="diagnosis-layout"><div class="diagnosis-main"><section class="diagnosis-conclusion panel"><div class="panel-heading"><div class="title-line"><AppIcon name="diagnosis" class="ai" /><h2>诊断结论</h2></div><Badge tone="ai">只读分析</Badge></div><div class="panel-pad"><p class="report-summary">{{ data.result?.summary||'等待报告通过服务端引用校验。可以离开此页，任务状态与检查点保存在服务端。' }}</p><p class="form-hint">{{ data.modelName==='mock'?'Mock 模式：按本地观测整理证据，未调用真实模型，不显示置信度。':'报告由已配置模型生成；模型自评未经校准，需人工核对证据。' }}</p></div></section>
<section class="panel graph-progress" aria-label="工具与诊断节点记录"><div class="panel-heading"><h2>工具与诊断节点</h2><span class="muted small">来自已保存的任务记录</span></div><ol><li v-for="(step,index) in data.steps" :key="step.node" :class="step.status.toLowerCase()"><span class="node-index"><AppIcon v-if="step.status==='COMPLETED'" name="check" :size="14" /><template v-else>{{ index+1 }}</template></span><strong>{{ nodeNames[step.node]||step.node }}</strong><small>{{ step.status==='COMPLETED'?'已确认':step.status==='FAILED'?'未完成':step.status==='SKIPPED'?'已跳过':'等待结果确认' }}</small><time v-if="step.completedAt">{{ time(step.completedAt) }}</time></li></ol><div class="panel-footnote">节点确认表示结果已保存并通过 Java 校验；未确认节点不推测执行中或耗时。<span v-if="data.errorCode"> 最近错误：{{ data.errorCode }} · 尝试 {{ data.attempts }}/5</span></div></section>
<section v-if="data.deliveryState==='DEAD'" class="panel retry-panel"><h2>诊断未完成</h2><p v-if="data.errorCode==='AGENT_MODEL_OUTCOME_UNKNOWN'" class="notice">模型调用是否完成无法确认。请先核对模型服务的调用记录；需要新诊断时，从事件详情明确发起。</p><p v-else>错误码 {{ data.errorCode }}。请确认内部诊断服务与配置，再由管理员明确重试。</p><form v-if="hasRole('OPS_ADMIN')&&data.errorCode!=='AGENT_MODEL_OUTCOME_UNKNOWN'" @submit.prevent="retry"><div v-if="saveError" class="error-message" role="alert">{{ saveError }}</div><label>重试理由<input v-model="reason" required maxlength="500" /></label><button class="btn" :disabled="busy||!reason.trim()">{{ busy?'提交中…':'重新加入队列' }}</button></form></section>
<template v-if="data.result"><section class="panel report-block"><div class="eyebrow ai">Inferred · 待确认推断</div><h2>诊断假设</h2><article v-for="(hypothesis,index) in data.result.hypotheses" :key="index" class="hypothesis"><div class="hypothesis-number">{{ String(index+1).padStart(2,'0') }}</div><div><p>{{ hypothesis.text }}</p><small class="muted">{{ hypothesis.evidenceIds.length }} 条引用<span v-if="hypothesisScore(data.modelName,hypothesis.confidence)"> · {{ hypothesisScore(data.modelName,hypothesis.confidence) }}</span></small><div class="evidence-links"><a v-for="evidence in hypothesis.evidenceIds" :key="evidence" :href="'#evidence-'+evidence" class="evidence-tag">{{ evidence.startsWith('check:')?'检查':'手册' }} {{ shortId(evidence.split(':')[1]||evidence) }}</a></div></div></article><p v-if="!data.result.hypotheses.length" class="muted">证据不足或没有异常检查，未形成故障假设。</p></section><section class="panel report-block"><div class="eyebrow">Suggested · 人工核对</div><h2>修复与排查建议</h2><ol class="next-steps"><li v-for="(step,index) in data.result.nextSteps" :key="index"><p>{{ step.text }}</p><Badge :tone="step.risk==='HIGH'?'danger':step.risk==='MEDIUM'?'warning':'neutral'">{{ ({LOW:'低风险',MEDIUM:'中风险',HIGH:'高风险'} as Record<string,string>)[step.risk]||step.risk }} · 需人工审阅</Badge></li></ol><p v-if="!data.result.nextSteps.length" class="muted">当前没有建议。</p></section><AgentReviewPanel :run="data" :can-operate="data.canOperate" @changed="load" /></template></div>
<aside class="diagnosis-evidence"><section class="panel"><div class="panel-heading"><div class="title-line"><AppIcon name="evidence" :size="17" /><h2>关联证据</h2></div><span class="heading-count">{{ data.checkEvidence.length+data.runbookEvidence.length }}</span></div><div class="evidence-section"><div class="eyebrow">Observed · 检查事实</div><article v-for="check in data.checkEvidence" :id="'evidence-check:'+check.runId" :key="check.runId" class="check-evidence"><div class="title-line"><StatusBadge :value="check.outcome" /><code>{{ check.statusCode??check.errorCode??'—' }}</code><small class="muted">{{ check.latencyMs===null?'未知延迟':check.latencyMs+' ms' }}</small></div><time>{{ time(check.completedAt) }}</time><RouterLink :to="{path:'/targets/'+data.targetId,query:{tab:'history'}}" class="text-link">检查 {{ shortId(check.runId) }}<AppIcon name="external" :size="12" /></RouterLink></article><p v-if="!data.checkEvidence.length" class="muted">当前窗口没有检查证据。</p></div><div class="evidence-section"><div class="eyebrow">Retrieved · 冻结知识</div><details v-for="section in data.runbookEvidence" :id="'evidence-runbook:'+section.sectionId" :key="section.sectionId" class="book-evidence"><summary>运行手册 v{{ section.version }} · {{ shortId(section.sectionId) }}</summary><p class="preserve-text">{{ section.text }}</p><RouterLink :to="citationLink(section.sectionId)" class="text-link">打开发布版本<AppIcon name="external" :size="12" /></RouterLink><small class="mono muted" :title="section.hash">SHA-256 {{ section.hash.slice(0,12) }}…</small></details><p v-if="!data.runbookEvidence.length" class="muted">没有引用的已发布手册。</p></div></section>
<section v-if="data.result" class="panel report-block boundaries"><div class="eyebrow">Unknown · 结论边界</div><h2>不确定项</h2><ul class="uncertainties"><li v-for="item in data.result.uncertainties" :key="item">{{ item==='insufficient_evidence'?'检查证据不足，无法确定故障原因。':item }}</li></ul><p v-if="!data.result.uncertainties.length" class="muted">报告未列出不确定项，仍须核对观测来源。</p><div class="panel-footnote">图版本 {{ data.graphVersion }}<br>provider {{ data.modelName }}</div></section><section v-if="data.result" class="panel report-block"><h2>引用清单</h2><ul class="citation-list"><li v-for="citation in data.result.citations" :key="citation.id"><RouterLink :to="citation.kind==='RUNBOOK_SECTION'?citationLink(citation.id):{path:'/targets/'+data.targetId,query:{tab:'history'}}">{{ citation.kind==='RUNBOOK_SECTION'?'手册 v'+citation.version:'检查记录' }} · {{ shortId(citation.id) }} ↗</RouterLink><small v-if="citation.time" class="muted">{{ time(citation.time) }}</small><small v-if="citation.hash" class="mono muted" :title="citation.hash">SHA-256 {{ citation.hash.slice(0,12) }}…</small></li></ul><p v-if="!data.result.citations.length" class="muted">没有可引用证据。</p></section></aside></div></template></PageState></template>
<style scoped>
.diagnosis-context{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:16px 0 24px;margin-bottom:24px;border-bottom:1px solid var(--border);font-size:13px}.diagnosis-context>a:first-of-type{flex:1;min-width:200px}.diagnosis-layout{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(300px,1fr);gap:24px;align-items:start}.diagnosis-main,.diagnosis-evidence{min-width:0;display:grid;gap:24px}.diagnosis-evidence{position:sticky;top:24px}.report-summary{font-size:16px;line-height:1.9}.graph-progress ol{list-style:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px 16px;padding:24px;margin:0}.graph-progress li{display:grid;grid-template-columns:28px 1fr;column-gap:8px;align-items:center}.node-index{width:28px;height:28px;display:grid;place-items:center;border-radius:8px;border:1px solid var(--border);color:var(--muted);grid-row:span 2;font-size:11px}.completed .node-index{color:var(--ai);background:color-mix(in srgb,var(--ai) 10%,transparent);border-color:color-mix(in srgb,var(--ai) 25%,var(--border))}.failed .node-index{color:var(--danger)}.graph-progress li strong{font-size:12px}.graph-progress li small{font-size:10px;color:var(--muted)}.graph-progress li time{font-size:9px;color:var(--muted);grid-column:1/-1;margin-top:6px}.report-block,.retry-panel{padding:24px}.report-block h2{margin:4px 0 16px}.hypothesis{display:flex;gap:16px;padding:20px 0;border-top:1px solid var(--border)}.hypothesis-number{font-size:14px;color:var(--ai);font-family:Consolas,monospace}.hypothesis p{margin-bottom:8px}.next-steps{padding-left:20px}.next-steps li{padding:12px 0 16px;border-bottom:1px solid var(--border)}.next-steps li:last-child{border:0}.next-steps p{margin-bottom:8px}.evidence-section{padding:24px;border-bottom:1px solid var(--border);font-size:12px}.evidence-section:last-child{border:0}.check-evidence{padding:16px 0;border-bottom:1px solid var(--border);scroll-margin:32px}.check-evidence:last-child{border:0;padding-bottom:0}.check-evidence time{display:block;font-size:10px;color:var(--muted);margin:8px 0}.book-evidence{margin-top:16px;scroll-margin:32px}.book-evidence summary{cursor:pointer;color:var(--ink);font-size:12px}.book-evidence p{margin:12px 0;font-size:12px;color:var(--muted)}.book-evidence small{display:block;margin-top:8px}.uncertainties{padding-left:16px;color:var(--muted);font-size:12px}.uncertainties li{margin:12px 0}.boundaries .panel-footnote{padding:16px 0 0;margin-top:16px}.citation-list{list-style:none;margin:0;padding:0}.citation-list li{display:grid;gap:6px;padding:12px 0;border-bottom:1px solid var(--border);font-size:12px}.citation-list a{color:var(--info)}.citation-list li:last-child{border:0}.retry-panel p{margin:12px 0}.retry-panel form{display:flex;flex-wrap:wrap;gap:16px;align-items:end}.retry-panel label{flex:1;min-width:180px}
@media(max-width:1200px){.diagnosis-layout{grid-template-columns:minmax(0,1.4fr) minmax(280px,1fr)}.graph-progress ol{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:900px){.diagnosis-layout{grid-template-columns:1fr}.diagnosis-evidence{position:static;grid-row:2}.graph-progress ol{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.graph-progress ol{grid-template-columns:repeat(2,minmax(0,1fr));padding:20px}.report-block,.evidence-section,.retry-panel{padding:20px}.diagnosis-context{font-size:12px}.report-summary{font-size:14px}}
</style>
